from pathlib import Path
from ledger import Ledger

backup = Path('.ledger.py.before')
with backup.open('x') as saved:
    saved.write(Path('ledger.py').read_text())

def probe(name, check):
    try:
        check()
    except AssertionError as error:
        print(f'REPRODUCED {name}: {error}')
    else:
        raise AssertionError(f'{name}: expected defect was not reproduced')

def constructor_alias():
    balances = {'a': 10, 'b': 0}
    ledger = Ledger(balances)
    balances['a'] = 0
    assert ledger.balances['a'] == 10, 'caller changed ledger through constructor input'

def invalid_balance():
    try:
        Ledger({'a': True})
    except ValueError:
        return
    raise AssertionError('boolean balance accepted')

def insufficient_funds():
    ledger = Ledger({'a': 10, 'b': 0})
    try:
        ledger.transfer('a', 'b', 11, 'overdraft')
    except ValueError:
        pass
    assert ledger.balances == {'a': 10, 'b': 0}, f'failed debit left {ledger.balances}'

def missing_account():
    ledger = Ledger({'a': 10, 'b': 0})
    error_type = None
    try:
        ledger.transfer('a', 'missing', 1, 'missing')
    except Exception as error:
        error_type = type(error).__name__
    assert error_type == 'ValueError' and ledger.balances == {'a': 10, 'b': 0}, f'{error_type}, state {ledger.balances}'

def conflicting_key():
    ledger = Ledger({'a': 10, 'b': 0})
    ledger.transfer('a', 'b', 2, 'one')
    try:
        ledger.transfer('a', 'b', 3, 'one')
    except ValueError:
        return
    raise AssertionError('changed payload silently replayed')

def receipt_alias():
    ledger = Ledger({'a': 10, 'b': 0})
    receipt = ledger.transfer('a', 'b', 2, 'one')
    receipt['amount'] = 9
    assert ledger.history['one']['amount'] == 2, 'returned receipt changed history'

def batch_rollback():
    ledger = Ledger({'a': 10, 'b': 0})
    try:
        ledger.batch([
            dict(source='a', target='b', amount=2, key='one'),
            dict(source='a', target='b', amount=20, key='two'),
        ])
    except ValueError:
        pass
    assert ledger.balances == {'a': 10, 'b': 0} and ledger.history == {}, f'partial batch survived: {ledger.balances}, {ledger.history}'

for name, check in [
    ('constructor isolation', constructor_alias),
    ('balance validation', invalid_balance),
    ('overdraft atomicity', insufficient_funds),
    ('unavailable account rejection', missing_account),
    ('idempotency conflict', conflicting_key),
    ('receipt isolation', receipt_alias),
    ('batch rollback', batch_rollback),
]:
    probe(name, check)
